void gc_keys(struct list_head *keys) {
    struct list_head *pos, *tmp;
    struct key *key;

    list_for_each_safe(pos, tmp, keys) {
        key = list_entry(pos, struct key, list);
        list_del(&key->list);

        if (key->user && key->in_quota) {
            key->user->nkeys--;
            key->user->qnkeys--;
            key->user->key_bytes -= key->datalen;
            key->user->qkey_bytes -= key->datalen;
        }

        if (key->type->destroy)
            key->type->destroy(key);

        key_cache_flush(key);
        key_put(key);
    }
}

